## Code Example
```javascript
function enforceContract(rec) {
  const required = ['customer_id', 'event_ts', 'value'];
  const missing = required.filter(field => rec[field] == null);
  if (missing.length > 0) {
    throw new Error(`Missing required fields: ${missing.join(', ')}`);
  }
  if (typeof rec.value !== 'number') {
    throw new Error('Value must be numeric');
  }
  return rec;
}
```

